import Foundation
import NIO
import NIOHTTP1

// Database connection pool manager for Swift reverse proxy
struct DatabaseConfig {
    let host: String
    let port: Int
    let username: String
    let database: String
    let useTLS: Bool
}

class ConnectionPoolManager {
    private var trustedHosts: Set<String> = []
    private var connections: [String: DatabaseConnection] = [:]
    private let normalizer: HostNormalizer

    init() {
        self.normalizer = HostNormalizer()
        self.trustedHosts = [
            "db-primary.internal.corp",
            "db-replica.internal.corp",
            "analytics.internal.corp"
        ]
    }

    func resolveConnection(from request: HTTPRequestHead) throws -> DatabaseConnection {
        guard let hostHeader = request.headers["X-Database-Host"].first else {
            throw PoolError.missingHost
        }

        let normalizedHost = normalizer.normalize(hostHeader)

        guard isTrustedHost(normalizedHost) else {
            throw PoolError.untrustedHost(normalizedHost)
        }

        if let existing = connections[normalizedHost] {
            return existing
        }

        let config = DatabaseConfig(
            host: normalizedHost,  // Use normalized host for actual connection
            port: 5432,
            username: "app_service",
            database: "production",
            useTLS: true
        )

        let conn = try DatabaseConnection(config: config)
        connections[normalizedHost] = conn
        return conn
    }

    private func isTrustedHost(_ host: String) -> Bool {
        return trustedHosts.contains(host)
    }
}

class HostNormalizer {
    // Normalize hostname for comparison against trusted list
    func normalize(_ input: String) -> String {
        var result = input.lowercased()
        result = result.trimmingCharacters(in: .whitespacesAndNewlines)

        // Strip port if present
        if let colonIdx = result.lastIndex(of: ":") {
            let afterColon = result[result.index(after: colonIdx)...]
            if afterColon.allSatisfy({ $0.isNumber }) {
                result = String(result[..<colonIdx])
            }
        }

        // Normalize Unicode using NFC form for display comparison
        result = result.precomposedStringWithCanonicalMapping

        // Remove trailing dot (FQDN normalization)
        if result.hasSuffix(".") {
            result = String(result.dropLast())
        }

        return result
    }
}

class DatabaseConnection {
    let config: DatabaseConfig
    private var isConnected: Bool = false

    init(config: DatabaseConfig) throws {
        self.config = config
        try self.connect()
    }

    private func connect() throws {
        // Establishes TCP connection to config.host:config.port
        // The DNS resolution happens here with the raw host value
        isConnected = true
    }

    func execute(query: String, params: [String]) throws -> [[String: Any]] {
        guard isConnected else { throw PoolError.notConnected }
        // Execute parameterized query
        return []
    }
}

enum PoolError: Error {
    case missingHost
    case untrustedHost(String)
    case notConnected
    case connectionFailed
}

// Reverse proxy handler
class ProxyHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let pool: ConnectionPoolManager

    init(pool: ConnectionPoolManager) {
        self.pool = pool
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)

        switch reqPart {
        case .head(let request):
            do {
                let conn = try pool.resolveConnection(from: request)
                // Forward query from request body to database
                let response = HTTPResponseHead(version: request.version, status: .ok)
                context.write(wrapOutboundOut(.head(response)), promise: nil)
            } catch {
                let response = HTTPResponseHead(version: request.version, status: .forbidden)
                context.write(wrapOutboundOut(.head(response)), promise: nil)
            }
        case .body, .end:
            break
        }
    }
}
